"""tabula.engine -- the table model, the transforms, the output formats and the command line.

This is the one module every command lives in. A command is a function `cmd_NAME(args, opts)` that gets the
positional arguments (a list of strings) and the options (a dict) and returns a Table, which `main` then prints in the
format asked for (`--format text|csv|json`, text by default). A mistake in a file or in a request raises TabulaError
(exit status 1); a command line that is not shaped right raises UsageError (exit status 2).
"""
import csv
import io
import json
import os
import re
import sys
import unicodedata
from decimal import Context, Decimal, InvalidOperation, ROUND_HALF_UP, ROUND_FLOOR, ROUND_CEILING, ROUND_DOWN, getcontext

from .errors import TabulaError, UsageError

PROG = "tabula"
FORMATS = ("text", "csv", "json")
# Every enumerated option: name -> allowed values, the first being the default. `parse_args` reads them all one way.
OPTIONS = {"format": FORMATS, "kind": ("inner", "left"), "keep": ("first", "last")}
getcontext().prec = 60

NUMBER = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)")


# --- numbers -------------------------------------------------------------------------------------------------

def to_decimal(text):
    """The Decimal a cell holds, or None when it is not a plain decimal number (no exponent, no thousands marks)."""
    text = text.strip()
    if not NUMBER.fullmatch(text):
        return None
    try:
        return Decimal(text)
    except InvalidOperation:
        return None


def fmt_decimal(number):
    """A Decimal as plain text: no exponent, no negative zero."""
    text = format(number, "f")
    if text.startswith("-") and not text.strip("-0."):
        text = text[1:]
    return text


def fmt_2dp(number):
    """A Decimal rounded half up to two decimals, always printed with two."""
    context = Context(prec=max(getcontext().prec, number.adjusted() + 10))
    return fmt_decimal(number.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP, context=context))


def _need_number(value):
    number = to_decimal(value)
    if number is None:
        raise TabulaError("%r is not a number" % value)
    return number


def _need_count(arg, name):
    if arg is None or not arg.isdigit():
        raise TabulaError("%s needs a whole number argument, got %r" % (name, arg))
    return int(arg)


def _need_decimal_arg(arg, name):
    number = None if arg is None else to_decimal(arg)
    if number is None:
        raise TabulaError("%s needs a number argument, got %r" % (name, arg))
    return number


def _cell_number(table, row_number, column, value):
    """The Decimal a cell holds; TabulaError naming file, row and column when it is not a number."""
    number = to_decimal(value)
    if number is None:
        raise TabulaError("%s: row %d: column %r: %r is not a number" % (table.source, row_number, column, value))
    return number


def _no_arg(name, arg):
    if arg is not None:
        raise TabulaError("%s takes no argument, got %r" % (name, arg))


def _need_text(arg, name):
    if arg is None:
        raise TabulaError("%s needs an argument" % name)
    return arg


# --- the table -----------------------------------------------------------------------------------------------

class Table:
    """Column names and rows of strings. `source` names where it came from, for messages."""

    def __init__(self, columns, rows, source="<table>"):
        self.columns = list(columns)
        self.rows = [list(r) for r in rows]
        self.source = source

    def __len__(self):
        return len(self.rows)

    def index(self, name):
        """Position of a column; TabulaError when there is none."""
        try:
            return self.columns.index(name)
        except ValueError:
            raise TabulaError("%s: no column %r (columns: %s)" % (self.source, name, ", ".join(self.columns)))

    def column(self, name):
        at = self.index(name)
        return [row[at] for row in self.rows]

    def dicts(self):
        return [dict(zip(self.columns, row)) for row in self.rows]

    def with_rows(self, rows, columns=None):
        return Table(self.columns if columns is None else columns, rows, self.source)


def parse_text(text, source):
    """CSV text into a Table. Blank lines are ignored; every row must have as many fields as the header."""
    if text.startswith("﻿"):
        text = text[1:]
    reader = csv.reader(io.StringIO(text, newline=""))
    columns, rows = None, []
    try:
        for fields in reader:
            if not fields:
                continue
            if columns is None:
                for name in fields:
                    if not name.strip():
                        raise TabulaError("%s: line %d: empty column name" % (source, reader.line_num))
                if len(set(fields)) != len(fields):
                    raise TabulaError("%s: line %d: duplicate column name" % (source, reader.line_num))
                columns = fields
                continue
            if len(fields) != len(columns):
                raise TabulaError("%s: line %d: expected %d fields, found %d"
                                  % (source, reader.line_num, len(columns), len(fields)))
            rows.append(fields)
    except csv.Error as exc:
        raise TabulaError("%s: line %d: %s" % (source, reader.line_num, exc))
    if columns is None:
        raise TabulaError("%s: no header line" % source)
    return Table(columns, rows, source)


def load(path):
    """Read a CSV file (UTF-8, optional byte order mark, LF or CRLF) into a Table."""
    try:
        with open(path, "rb") as fh:
            raw = fh.read()
    except OSError as exc:
        raise TabulaError("%s: cannot read: %s" % (path, exc.strerror or exc))
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise TabulaError("%s: not valid UTF-8" % path)
    return parse_text(text, path)


# --- output --------------------------------------------------------------------------------------------------

def render_text(table):
    cells = [table.columns] + table.rows
    widths = [max(len(row[i]) for row in cells) for i in range(len(table.columns))]
    lines = ["  ".join(cell.ljust(width) for cell, width in zip(row, widths)).rstrip() for row in cells]
    return "\n".join(lines) + "\n"


def render_csv(table):
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(table.columns)
    writer.writerows(table.rows)
    return out.getvalue()


def render_json(table):
    return json.dumps(table.dicts(), ensure_ascii=False) + "\n"


RENDERERS = {"text": render_text, "csv": render_csv, "json": render_json}


def render(table, fmt="text"):
    return RENDERERS[fmt](table)


# --- transforms: one small function each, `name` or `name:ARG` in `apply` ----------------------------------------


def t_upper(value, arg=None):
    """The value in upper case.
def parse_spec(spec):
    """`name` or `name:arg` into (function, arg); the argument is everything after the first colon."""
    name, _, arg = spec.partition(":")
    if name not in TRANSFORMS:
        raise TabulaError("unknown transform %r" % name)
    return TRANSFORMS[name], (arg if ":" in spec else None)


def apply_transforms(value, specs):
    for fn, arg in specs:
        value = fn(value, arg)
    return value


# --- commands ------------------------------------------------------------------------------------------------

def _need_args(args, count, usage):
    if len(args) != count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def _need_at_least(args, count, usage):
    if len(args) < count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def cmd_show(args, opts):
    _need_args(args, 1, "show FILE")
    return load(args[0])


def cmd_head(args, opts):
    _need_args(args, 2, "head FILE N")
    if not args[1].isdigit():
        raise UsageError("head: N must be a whole number, got %r" % args[1])
    table = load(args[0])
    return table.with_rows(table.rows[:int(args[1])])


def cmd_cols(args, opts):
    _need_args(args, 1, "cols FILE")
    table = load(args[0])
    return Table(["position", "column"], [[str(i + 1), name] for i, name in enumerate(table.columns)], table.source)


def cmd_apply(args, opts):
    _need_at_least(args, 3, "apply FILE COLUMN TRANSFORM...")
    table = load(args[0])
    at = table.index(args[1])
    specs = [parse_spec(s) for s in args[2:]]
    rows = []
    for number, row in enumerate(table.rows, 1):
        row = list(row)
        try:
            row[at] = apply_transforms(row[at], specs)
        except TabulaError as exc:
            raise TabulaError("%s: row %d: %s" % (table.source, number, exc))
        rows.append(row)
    return table.with_rows(rows)


def _parse_sort_key(key):
    """(column, numeric, descending) from `COLUMN[:num][:desc]`; UsageError for anything else."""
    column, *modifiers = key.split(":")
    if not column:
        raise UsageError("sort: empty column name in key %r" % key)
    for modifier in modifiers:
        if modifier not in ("num", "desc"):
            raise UsageError("sort: unknown modifier %r in key %r" % (modifier, key))
    if len(set(modifiers)) != len(modifiers):
        raise UsageError("sort: modifier given twice in key %r" % key)
    return column, "num" in modifiers, "desc" in modifiers


def cmd_sort(args, opts):
    _need_at_least(args, 2, "sort FILE KEY...")
    keys = [_parse_sort_key(k) for k in args[1:]]
    table = load(args[0])
    positions = [table.index(column) for column, _, _ in keys]
    values = []  # per row, per key: what that key compares on
    for number, row in enumerate(table.rows, 1):
        values.append([_cell_number(table, number, column, row[at]) if numeric else row[at]
                       for (column, numeric, _), at in zip(keys, positions)])
    order = list(range(len(table.rows)))
    for k in range(len(keys) - 1, -1, -1):  # stable passes, last key first; reverse=True keeps ties in order too
        order.sort(key=lambda i: values[i][k], reverse=keys[k][2])
    return table.with_rows([table.rows[i] for i in order])


FILTER_OPERATORS = ("==", "!=", ">=", "<=", ">", "<", "~")
_FILTER_TESTS = {
    "==": lambda a, b: a == b, "!=": lambda a, b: a != b, ">=": lambda a, b: a >= b,
    "<=": lambda a, b: a <= b, ">": lambda a, b: a > b, "<": lambda a, b: a < b,
}


def _parse_condition(arg):
    """(column, operator, value) from `COLUMN OP VALUE`: the earliest operator, the longer one at the same place."""
    best = None
    for op in FILTER_OPERATORS:
        at = arg.find(op)
        if at >= 0 and (best is None or at < best[0] or (at == best[0] and len(op) > len(best[1]))):
            best = (at, op)
    if best is None:
        raise UsageError("filter: no operator (one of %s) in condition %r" % (" ".join(FILTER_OPERATORS), arg))
    at, op = best
    if at == 0:
        raise UsageError("filter: empty column name in condition %r" % arg)
    return arg[:at], op, arg[at + len(op):]


def _condition_holds(cell, op, value, number):
    """Whether one cell passes; numbers compare as numbers when both sides are, else by code point."""
    if op == "~":
        return value.lower() in cell.lower()
    if number is not None:
        cell_number = to_decimal(cell)
        if cell_number is not None:
            return _FILTER_TESTS[op](cell_number, number)
    return _FILTER_TESTS[op](cell, value)


def cmd_filter(args, opts):
    _need_at_least(args, 2, "filter FILE CONDITION...")
    conditions = [_parse_condition(a) for a in args[1:]]
    table = load(args[0])
    tests = [(table.index(column), op, value, to_decimal(value)) for column, op, value in conditions]
    return table.with_rows([row for row in table.rows
                            if all(_condition_holds(row[at], op, value, number) for at, op, value, number in tests)])


GROUP_FUNCTIONS = ("sum", "min", "max", "mean")


def _parse_aggregate(spec):
    """(function, column or None) from `count` or `FUNCTION:COLUMN`; UsageError for anything else."""
    if spec == "count":
        return "count", None
    function, colon, column = spec.partition(":")
    if function not in GROUP_FUNCTIONS or not colon or not column:
        raise UsageError("group: %r is not an aggregate (count, sum:COLUMN, min:COLUMN, max:COLUMN or mean:COLUMN)" % spec)
    return function, column


def _aggregate(function, numbers, count):
    """One group's result cell. Sums run in a context wide enough to lose no digit."""
    if function == "count":
        return str(count)
    if function in ("min", "max"):
        return fmt_decimal((min if function == "min" else max)(numbers))
    digits = sum(len(n.as_tuple().digits) for n in numbers) + 10
    context = Context(prec=digits)
    total = Decimal(0)
    for n in numbers:
        total = context.add(total, n)
    if function == "sum":
        return fmt_decimal(total)
    return fmt_2dp(Context(prec=digits + len(str(count))).divide(total, Decimal(count)))


def cmd_group(args, opts):
    _need_at_least(args, 3, "group FILE BY AGGREGATE...")
    if len(set(args[2:])) != len(args[2:]):
        raise UsageError("group: the same aggregate is given twice")
    aggregates = [_parse_aggregate(a) for a in args[2:]]
    table = load(args[0])
    by = table.index(args[1])
    positions = [None if column is None else table.index(column) for _, column in aggregates]
    names = [spec.replace(":", "_") for spec in args[2:]]
    result_columns = [table.columns[by]] + names
    for name in result_columns:
        if result_columns.count(name) > 1:
            raise TabulaError("group: the result would have column %r twice" % name)
    groups = {}  # BY value -> [row count, one list of numbers per aggregate]
    for number, row in enumerate(table.rows, 1):
        group = groups.setdefault(row[by], [0, [[] for _ in aggregates]])
        group[0] += 1
        for (_, column), at, found in zip(aggregates, positions, group[1]):
            if at is not None:
                found.append(_cell_number(table, number, column, row[at]))
    rows = [[value] + [_aggregate(function, found, count) for (function, _), found in zip(aggregates, numbers)]
            for value, (count, numbers) in groups.items()]
    return Table(result_columns, rows, table.source)


def cmd_join(args, opts):
    _need_args(args, 3, "join LEFT RIGHT KEY")
    left, right = load(args[0]), load(args[1])
    left_at, right_at = left.index(args[2]), right.index(args[2])
    kept = [i for i in range(len(right.columns)) if i != right_at]
    columns = left.columns + [right.columns[i] + "_right" if right.columns[i] in left.columns else right.columns[i]
                              for i in kept]
    for name in columns:
        if columns.count(name) > 1:
            raise TabulaError("join: the result would have column %r twice" % name)
    matches = {}  # KEY text -> the RIGHT rows with it, in the order of RIGHT
    for row in right.rows:
        matches.setdefault(row[right_at], []).append([row[i] for i in kept])
    unmatched = [[""] * len(kept)] if opts["kind"] == "left" else []
    rows = [lrow + rrow for lrow in left.rows for rrow in matches.get(lrow[left_at], unmatched)]
    return Table(columns, rows, left.source)


def cmd_pivot(args, opts):
    _need_args(args, 4, "pivot FILE ROW COLUMN VALUE")
    if args[1] == args[2]:
        raise UsageError("pivot: ROW and COLUMN must be different columns, got %r twice" % args[1])
    table = load(args[0])
    row_at, column_at, value_at = table.index(args[1]), table.index(args[2]), table.index(args[3])
    sums = {}  # (ROW value, COLUMN value) -> the numbers to add
    row_values, column_values = {}, {}  # first-appearance order
    for number, row in enumerate(table.rows, 1):
        label = row[column_at]
        if label.strip() == "":
            raise TabulaError("%s: row %d: column %r: empty value" % (table.source, number, args[2]))
        if label == table.columns[row_at]:
            raise TabulaError("%s: row %d: column %r: value %r is the name of the row column"
                              % (table.source, number, args[2], label))
        found = _cell_number(table, number, args[3], row[value_at])
        row_values.setdefault(row[row_at])
        column_values.setdefault(label)
        sums.setdefault((row[row_at], label), []).append(found)
    rows = [[value] + [_aggregate("sum", sums[(value, label)], 0) if (value, label) in sums else "0"
                       for label in column_values] for value in row_values]
    return Table([table.columns[row_at]] + list(column_values), rows, table.source)


def cmd_dedupe(args, opts):
    _need_at_least(args, 2, "dedupe FILE KEY...")
    table = load(args[0])
    positions = [table.index(key) for key in args[1:]]
    chosen = {}  # KEY cells -> position of the row that stays (the first or the last one with them)
    for number, row in enumerate(table.rows):
        cells = tuple(row[at] for at in positions)
        if opts["keep"] == "last" or cells not in chosen:
            chosen[cells] = number
    staying = set(chosen.values())
    return table.with_rows([row for number, row in enumerate(table.rows) if number in staying])


def _median(numbers):
    """The middle number of a sorted list; of an even count, the exact mean of the two middle ones."""
    middle = len(numbers) // 2
    if len(numbers) % 2:
        return numbers[middle]
    a, b = numbers[middle - 1], numbers[middle]
    context = Context(prec=len(a.as_tuple().digits) + len(b.as_tuple().digits) + 10)
    return context.divide(context.add(a, b), Decimal(2))


def cmd_stats(args, opts):
    _need_at_least(args, 2, "stats FILE COLUMN...")
    table = load(args[0])
    positions = [table.index(column) for column in args[1:]]
    found = [[] for _ in positions]
    for number, row in enumerate(table.rows, 1):
        for column, at, numbers in zip(args[1:], positions, found):
            if row[at].strip() != "":
                numbers.append(_cell_number(table, number, column, row[at]))
    rows = []
    for column, numbers in zip(args[1:], found):
        if not numbers:
            rows.append([column, "0", "", "", "", ""])
            continue
        rows.append([column, str(len(numbers)), _aggregate("min", numbers, 0), _aggregate("max", numbers, 0),
                     _aggregate("mean", numbers, len(numbers)), fmt_2dp(_median(sorted(numbers)))])
    return Table(["column", "count", "min", "max", "mean", "median"], rows, table.source)


COMMANDS = {
    "show": (cmd_show, "show FILE", "print a table"),
    "head": (cmd_head, "head FILE N", "the first N rows"),
    "cols": (cmd_cols, "cols FILE", "the column names, numbered"),
    "apply": (cmd_apply, "apply FILE COLUMN TRANSFORM...", "run transforms over one column"),
    "sort": (cmd_sort, "sort FILE KEY...", "rows sorted by KEYs (COLUMN[:num][:desc])"),
    "filter": (cmd_filter, "filter FILE CONDITION...", "rows where every COLUMN OP VALUE holds (== != >= <= > < ~)"),
    "group": (cmd_group, "group FILE BY AGGREGATE...", "one row per BY value: count, sum:COL, min:COL, max:COL, mean:COL"),
    "join": (cmd_join, "join LEFT RIGHT KEY", "LEFT rows with the RIGHT rows of the same KEY (--kind inner|left)"),
    "pivot": (cmd_pivot, "pivot FILE ROW COLUMN VALUE", "sums of VALUE, one row per ROW value, one column per COLUMN value"),
    "dedupe": (cmd_dedupe, "dedupe FILE KEY...", "drop rows repeating the KEY columns (--keep first|last)"),
    "stats": (cmd_stats, "stats FILE COLUMN...", "count, min, max, mean and median of the numbers in each COLUMN"),
}


# --- the command line ----------------------------------------------------------------------------------------

def usage_text():
    lines = ["usage: %s [--format text|csv|json] [--kind inner|left] [--keep first|last] COMMAND ARGS..." % PROG, "", "commands:"]
    width = max(len(u) for _, u, _ in COMMANDS.values())
    for _, use, what in COMMANDS.values():
        lines.append("  %s  %s" % (use.ljust(width), what))
    return "\n".join(lines) + "\n"


def parse_args(argv):
    """(command, positional arguments, options) from the command line."""
    opts, rest, i = {name: values[0] for name, values in OPTIONS.items()}, [], 0
    while i < len(argv):
        arg = argv[i]
        name, has_value, value = arg[2:].partition("=")
        if arg in ("-h", "--help"):
            opts["help"] = True
        elif arg.startswith("--") and name in OPTIONS:
            if not has_value:
                i += 1
                if i >= len(argv):
                    raise UsageError("--%s needs a value" % name)
                value = argv[i]
            if value not in OPTIONS[name]:
                raise UsageError("--%s must be one of %s, got %r" % (name, ", ".join(OPTIONS[name]), value))
            opts[name] = value
        elif arg.startswith("-") and len(arg) > 1:
            raise UsageError("unknown option %s" % arg)
        else:
            rest.append(arg)
        i += 1
    if opts.get("help"):
        return None, rest, opts
    if not rest:
        raise UsageError("no command given")
    if rest[0] not in COMMANDS:
        raise UsageError("unknown command %r" % rest[0])
    return rest[0], rest[1:], opts


def _drop_stdout():
    """Point standard output at the null device so the flush at exit cannot fail again."""
    try:
        os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def main(argv=None):
    argv = sys.argv[1:] if argv is None else list(argv)
    try:
        name, args, opts = parse_args(argv)
        if name is None:
            sys.stdout.write(usage_text())
            return 0
        table = COMMANDS[name][0](args, opts)
        sys.stdout.write(render(table, opts["format"]))
        sys.stdout.flush()
        return 0
    except UsageError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 2
    except TabulaError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 1
    except BrokenPipeError:
        _drop_stdout()
        return 0
    except OSError as exc:  # standard output cannot be written (a full disk, a closed descriptor)
        _drop_stdout()
        print("%s: cannot write output: %s" % (PROG, exc.strerror or exc), file=sys.stderr)
        return 1

